import { UserInfo } from "@/types/user";
import ajax from "@/utils/ajax";
import { action, observable, makeObservable } from "mobx";
import userStore from "@code/store/user";
import React from "react";


class Store {

    iframeRef = React.createRef<any>();

    @observable isReady = false;
    @action setIsReady = (bool: boolean) => {
        this.isReady = bool;
    }

    @observable hidden = false;
    @action setHidden = (bool) => {
        this.hidden = bool;
    }

    @observable visible = false;
    @action setVisible = (bool) => {
        this.visible = bool;
    }


    @observable userList: UserInfo[] = [];
    @action setUserList = (list: any[]) => {
        this.userList = list;
    }

    // 获取当前用户列表
    getUserInfo = () => {
        ajax.post('/template/getUserList', {
        }).then((res)=> {
            this.setUserList(res.data);
        })
    }

    isOne = false;

    // 切换到xx用户
    changeLogin = (loginname) => {
        return ajax.post('/dev/UserLogin', {
            loginname,
        }).then((res) => {
            this.isOne = true;
            userStore.setInfo(res.data);
        })
    }


    init = () => {
        // 获取用户信息
        this.getUserInfo();
    }

    constructor(){
        makeObservable(this);
        this.init();
    }

}


export default Store;